-- `fk_set_null_index_size_before_later_unique_loud` through `ON UPDATE SET NULL`.
-- @setup
CREATE TABLE p (k text PRIMARY KEY);
INSERT INTO p VALUES ('a');
CREATE TABLE c (id int, k text REFERENCES p ON UPDATE SET NULL, pad text);
CREATE INDEX c_a ON c (pad, k);
CREATE UNIQUE INDEX c_b ON c (k) NULLS NOT DISTINCT;
INSERT INTO c VALUES (1, 'a', ''), (2, NULL, 'short');
-- @test
-- @expect-error: the first index's size before the second's duplicate
-- @expect-message
-- @profile-lock
UPDATE p SET k = 'z' WHERE k = 'a';
